WITH base AS (SELECT *, CASE WHEN device = 'tablet' THEN 1 ELSE 0 END is_tablet, COALESCE(browser, 'UNKNOWN') browser_filled FROM sessions WHERE customer_id IS NOT NULL AND started_at >= TIMESTAMP '2023-02-21 11:00:00') SELECT id, browser, started_at, country, is_tablet FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device ORDER BY is_tablet DESC NULLS LAST, id) AS rn FROM base) x WHERE rn = 1;
